query IssueByNumber($owner: String!, $repo: String!, $number: Int!) {
    repository(owner: $owner, name: $repo) {
      hasIssuesEnabled
      issue: issueOrPullRequest(number: $number) {
        __typename
        ...on Issue{id,number,title,body,url,labels(first:100){nodes{id,name,description,color},totalCount}}
        ...on PullRequest{id,number,title,body,url,labels(first:100){nodes{id,name,description,color},totalCount}}
      }
    }
  }
